      [("éducation thérapeutique","On explique aux parents, avec un interprète, le calendrier et les réactions attendues.","On augmente l'adhésion et l'on évite les rendez-vous manqués."),("soins infirmiers","On inscrit chaque dose avec la date et le nom exact du vaccin dans un carnet remis à la famille.","On évite les doses en double lors des transferts."),("social et assurances","On informe sur l'exemption de franchise et sur les vaccins de voyage non remboursés.","On lève un frein financier et l'on évite les surprises.")],
